<template>
  <div class="app-container accounting-page">
    <header class="hero"><div><span>DAILY BUSINESS LEDGER</span><h1>公司每日收支</h1><p>按公司、项目和日期记录经营事实，确认后自动生成项目盈亏快照。</p></div><el-button type="primary" icon="Plus" @click="openFact()">录入收支</el-button></header>
    <el-card shadow="never" class="filter-card"><el-form :inline="true" :model="query"><el-form-item><el-select v-model="query.companyDeptId" clearable placeholder="两家公司" style="width:190px"><el-option v-for="c in data.companies" :key="c.companyDeptId" :label="c.companyName" :value="c.companyDeptId" /></el-select></el-form-item><el-form-item><el-select v-model="query.projectId" clearable filterable placeholder="全部本人项目" style="width:220px"><el-option v-for="p in filteredProjects" :key="p.projectId" :label="`${p.projectName} · ${p.initiatorName}`" :value="p.projectId" /></el-select></el-form-item><el-form-item><el-date-picker v-model="dates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" /></el-form-item><el-form-item><el-button type="primary" @click="load">查询</el-button><el-button @click="reset">今天</el-button></el-form-item></el-form></el-card>
    <section class="summary-grid"><article><span>确认收入</span><b>{{ money(summary.revenueAmount) }}</b></article><article><span>业务成本</span><b>{{ money(summary.businessCost) }}</b></article><article><span>人员成本</span><b>{{ money(summary.personnelCost) }}</b></article><article><span>项目奖金</span><b>{{ money(summary.bonusCost) }}</b></article><article><span>核算调整</span><b>{{ signed(summary.adjustmentAmount) }}</b></article><article :class="Number(summary.profitAmount)<0?'loss':'profit'"><span>经营结果</span><b>{{ signed(summary.profitAmount) }}</b></article><article><span>已生成经营结果</span><b>{{ summary.resultCount || 0 }}</b></article></section>
    <el-card shadow="never" class="section-card personnel-card"><div class="section-head"><div><h2>人员成本核算</h2><p>核算日 {{ personnel.bizDate || dates?.[1] }}；月度成本按员工国家折算，实际投入已确认时覆盖计划投入。</p></div><div class="personnel-tools"><el-switch v-model="issuesOnly" inline-prompt active-text="待完善" inactive-text="全部"/><el-button link type="primary" @click="router.push('/business/staff')">人员成本设置</el-button></div></div><div class="personnel-summary"><div><span>当日预计成本</span><b>{{ money(personnel.personnelCost) }}</b></div><div><span>核算就绪</span><b>{{ personnel.readyCount || 0 }}</b></div><div :class="Number(personnel.issueCount)>0?'warn-box':''"><span>待完善</span><b>{{ personnel.issueCount || 0 }}</b></div><div :class="Number(personnel.overAllocatedCount)>0?'danger-box':''"><span>投入超额</span><b>{{ personnel.overAllocatedCount || 0 }}</b></div></div><el-alert v-if="personnel.issueCount" title="待完善人员不会正常产生项目人员成本：老板补充国家和月度成本，项目主负责人补充投入比例。" type="warning" :closable="false" show-icon/><el-table :data="visiblePersonnelRows" size="small" empty-text="当前筛选范围没有参项人员"><el-table-column label="项目 / 人员" min-width="190"><template #default="{row}"><b>{{ row.projectName }}</b><small>{{ row.userName }} · {{ row.companyName || '未设置公司' }}</small></template></el-table-column><el-table-column label="国家" width="75"><template #default="{row}">{{ row.costStatus==='MISSING_REGION'?'未设置':regionLabel(row.countryRegion) }}</template></el-table-column><el-table-column label="月度用人成本" min-width="125" align="right"><template #default="{row}">{{ row.monthlyCost==null?'未设置':money(row.monthlyCost) }}</template></el-table-column><el-table-column label="折算日成本" min-width="135" align="right"><template #default="{row}"><span v-if="row.dailyCost!=null">{{ money(row.dailyCost) }}</span><small v-if="row.standardWorkDays">÷ {{ row.standardWorkDays }} 天</small></template></el-table-column><el-table-column label="项目投入" width="110" align="right"><template #default="{row}"><span v-if="row.appliedPercent!=null">{{ row.appliedPercent }}%</span><small>{{ inputSourceLabel[row.inputSource] || '未设置' }}</small></template></el-table-column><el-table-column label="当日成本" width="115" align="right"><template #default="{row}"><b>{{ money(row.personnelCost) }}</b></template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="costStatusTone[row.costStatus]">{{ costStatusLabel[row.costStatus] || row.costStatus }}</el-tag></template></el-table-column><el-table-column label="处理" width="105"><template #default="{row}"><el-button v-if="row.costStatus==='MISSING_REGION'" link type="primary" @click="openStaffProfile(row)">设置国家</el-button><el-button v-else-if="['MISSING_COST','LEGACY_COST'].includes(row.costStatus)" link type="primary" @click="openStaffCost(row)">设置成本</el-button><el-button v-else-if="row.costStatus==='MISSING_ALLOCATION'" link type="primary" @click="openAllocation(row)">查看项目</el-button><span v-else>—</span></template></el-table-column></el-table></el-card>
    <el-card shadow="never" class="section-card"><div class="section-head"><div><h2>项目日结果</h2><p>每次确认、冲销或手动重算都会生成新版本，点击可查看计算分项。</p></div><el-button @click="openRecalculate">手动重算</el-button></div><el-table :data="data.results" @row-click="openResult" class="click-table"><el-table-column prop="bizDate" label="日期" width="105"/><el-table-column label="项目" min-width="190"><template #default="{row}"><b>{{ row.projectName }}</b><small>{{ row.companyName }} · {{ row.initiatorName }}立项</small></template></el-table-column><el-table-column label="收入" align="right"><template #default="{row}">{{ money(row.revenueAmount) }}</template></el-table-column><el-table-column label="业务成本" align="right"><template #default="{row}">{{ money(row.costAmount) }}</template></el-table-column><el-table-column label="人员成本" align="right"><template #default="{row}">{{ money(row.personnelCost) }}</template></el-table-column><el-table-column label="项目奖金" align="right"><template #default="{row}">{{ money(row.bonusCost) }}</template></el-table-column><el-table-column label="经营结果" align="right"><template #default="{row}"><b :class="Number(row.profitAmount)<0?'red':'green'">{{ signed(row.profitAmount) }}</b></template></el-table-column><el-table-column label="版本" width="70"><template #default="{row}">v{{ row.resultVersion }}</template></el-table-column></el-table></el-card>
    <el-card shadow="never" class="section-card"><div class="section-head"><div><h2>收支流水</h2><p>{{ isBoss?'草稿可确认入账或退回修改；已确认流水只允许冲销。':'已退回的收支可根据原因修改并重新提交。' }}</p></div></div><el-table :data="data.facts"><el-table-column prop="bizDate" label="日期" width="105"/><el-table-column label="项目" min-width="170"><template #default="{row}">{{ row.projectName }}<small>{{ row.companyName }}</small></template></el-table-column><el-table-column prop="categoryName" label="类别"/><el-table-column prop="description" label="说明" min-width="180"/><el-table-column label="金额/数值" align="right"><template #default="{row}"><b>{{ row.factKind==='VALUE'?`${row.quantity} ${row.unit||''}`:`${signed(row.amount)} ${row.currency||''}` }}</b></template></el-table-column><el-table-column label="状态" min-width="135"><template #default="{row}"><el-tag :type="statusTone[row.status]">{{ statusLabel[row.status] || row.status }}</el-tag><small v-if="row.status==='RETURNED'" class="return-reason">原因：{{ row.returnReason }}</small></template></el-table-column><el-table-column label="操作" min-width="210"><template #default="{row}"><el-button v-if="isBoss" link type="primary" @click="openFact(row,true)">查看详情</el-button><el-button v-else-if="['DRAFT','RETURNED'].includes(row.status)" link @click="openFact(row)">{{ row.status==='RETURNED'?'修改并重新提交':'编辑' }}</el-button><el-button v-if="isBoss&&row.status==='DRAFT'" link type="success" @click="confirmFact(row)">确认入账</el-button><el-button v-if="isBoss&&row.status==='DRAFT'" link type="warning" @click="returnFact(row)">退回修改</el-button><el-button v-if="isBoss&&row.status==='CONFIRMED'" link type="danger" @click="reverseFact(row)">冲销</el-button></template></el-table-column></el-table></el-card>

    <el-dialog v-model="factDialog" :title="factReadOnly?'收支流水详情':factForm.factId?'编辑收支草稿':'录入每日收支'" width="min(680px,94vw)" append-to-body><el-alert :title="factReadOnly?'当前为查看详情，所有数据均为只读状态。':'保存后先进入草稿；老板确认后才会计入正式日报。'" type="info" :closable="false" show-icon/><el-alert v-if="factForm.status==='RETURNED'" class="return-alert" :title="`退回原因：${factForm.returnReason||'未填写'}`" :description="`${factForm.returnedUserName||'老板'} 于 ${factForm.returnedTime||'—'} 退回，修改保存后将重新进入待确认。`" type="warning" :closable="false" show-icon/><el-form :model="factForm" :disabled="factReadOnly" label-width="92px" class="dialog-form"><el-form-item label="归属项目" required><el-select v-model="factForm.projectId" :disabled="factReadOnly||!!factForm.factId" filterable style="width:100%" @change="projectChanged"><el-option v-for="p in data.projects" :key="p.projectId" :label="`${p.projectName} · ${p.companyName||'未设置公司'}`" :value="p.projectId" /></el-select></el-form-item><el-form-item label="业务日期" required><el-date-picker v-model="factForm.bizDate" type="date" value-format="YYYY-MM-DD" style="width:100%" /></el-form-item><el-form-item label="收支类别" required><el-select v-model="factForm.categoryId" style="width:100%"><el-option-group v-for="group in categoryGroups" :key="group.kind" :label="group.label"><el-option v-for="c in group.items" :key="c.categoryId" :label="c.categoryName" :value="c.categoryId" /></el-option-group></el-select></el-form-item><template v-if="selectedCategory?.factKind==='VALUE'"><el-form-item label="成果数值" required><el-input-number v-model="factForm.quantity" :precision="4" style="width:100%" /></el-form-item><el-form-item label="单位"><el-input v-model="factForm.unit" /></el-form-item></template><template v-else><el-form-item label="金额" required><el-input-number v-model="factForm.amount" :precision="4" style="width:100%" /></el-form-item><el-form-item label="币种"><el-input v-model="factForm.currency" maxlength="3" /></el-form-item></template><el-form-item label="收支说明" required><el-input v-model="factForm.description" type="textarea" :rows="3" maxlength="500" show-word-limit /></el-form-item><el-form-item label="对方单位"><el-input v-model="factForm.counterparty" /></el-form-item><el-form-item label="凭证附件"><business-file-upload v-if="factReadOnly" :model-value="factForm.attachmentUrls" :project-id="factForm.projectId" disabled :drag="false" :is-show-tip="false"/><business-file-upload v-else v-model="factForm.attachmentUrls" :project-id="factForm.projectId" /></el-form-item><el-form-item label="备注"><el-input v-model="factForm.remark" type="textarea" :rows="2" /></el-form-item></el-form><template #footer><el-button @click="factDialog=false">{{ factReadOnly?'关闭':'取消' }}</el-button><el-button v-if="!factReadOnly" type="primary" :loading="saving" @click="saveFact">{{ factForm.status==='RETURNED'?'修改并重新提交':'保存草稿' }}</el-button></template></el-dialog>
    <el-dialog v-model="recalcDialog" title="重算项目日结果" width="min(500px,94vw)" append-to-body><el-form :model="recalcForm" label-width="90px"><el-form-item label="项目" required><el-select v-model="recalcForm.projectId" filterable style="width:100%"><el-option v-for="p in data.projects" :key="p.projectId" :label="p.projectName" :value="p.projectId" /></el-select></el-form-item><el-form-item label="业务日期" required><el-date-picker v-model="recalcForm.bizDate" type="date" value-format="YYYY-MM-DD" style="width:100%" /></el-form-item></el-form><template #footer><el-button @click="recalcDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveRecalculate">开始重算</el-button></template></el-dialog>
    <el-drawer v-model="resultDrawer" title="项目日结果计算明细" size="min(760px,96vw)" append-to-body><template v-if="resultDetail"><div class="result-title"><div><b>{{ resultDetail.projectName }}</b><span>{{ resultDetail.bizDate }} · v{{ resultDetail.resultVersion }}</span></div><strong :class="Number(resultDetail.profitAmount)<0?'red':'green'">{{ signed(resultDetail.profitAmount) }}</strong></div><el-alert :title="resultDetail.calculationDetail" type="info" :closable="false"/><el-table :data="resultDetail.items" class="item-table"><el-table-column prop="componentName" label="计算分项"/><el-table-column label="金额" align="right"><template #default="{row}">{{ signed(row.amount) }}</template></el-table-column><el-table-column prop="calculationDetail" label="来源说明" min-width="190"/></el-table><section class="personnel-detail"><div class="personnel-title"><div><h3>人员成本明细</h3><p>月度成本 ÷ 标准工作日 × 本项目投入比例；请假为 0。</p></div><b>{{ money(resultDetail.personnelCost) }} {{ resultDetail.currency||'CNY' }}</b></div><el-table v-if="resultDetail.personnelItems?.length" :data="resultDetail.personnelItems" size="small"><el-table-column prop="componentName" label="人员" width="100"/><el-table-column label="月度成本" width="115" align="right"><template #default="{row}">{{ row.monthlyCost==null?'历史快照':money(row.monthlyCost) }}</template></el-table-column><el-table-column label="折算" min-width="125"><template #default="{row}"><span v-if="row.standardWorkDays">{{ regionLabel(row.countryRegion) }} / {{ row.standardWorkDays }} 天</span><span v-else>—</span></template></el-table-column><el-table-column label="投入" width="90" align="right"><template #default="{row}">{{ row.appliedPercent==null?'—':`${row.appliedPercent}%` }}<small>{{ inputSourceLabel[row.inputSource] }}</small></template></el-table-column><el-table-column label="核算金额" width="110" align="right"><template #default="{row}"><b>{{ money(row.amount) }}</b></template></el-table-column><el-table-column prop="calculationDetail" label="计算依据" min-width="220"/></el-table><el-empty v-else description="本日没有计入人员成本的参项人员" :image-size="70"/></section></template></el-drawer>
  </div>
</template>

<script setup name="BusinessAccounting">
import {ElMessage,ElMessageBox} from 'element-plus'
import {confirmBusinessOperatingFact,getBusinessAccountingDashboard,getBusinessDailyResult,getBusinessPersonnelCostOverview,recalculateBusinessProjectDay,returnBusinessOperatingFact,reverseBusinessOperatingFact,saveBusinessOperatingFact} from '@/api/business/accounting'
import useUserStore from '@/store/modules/user'
const today=()=>{const now=new Date();const local=new Date(now.getTime()-now.getTimezoneOffset()*60000);return local.toISOString().slice(0,10)}
const route=useRoute()
const router=useRouter()
const userStore=useUserStore()
const query=reactive({companyDeptId:route.query.companyDeptId?Number(route.query.companyDeptId):null,projectId:route.query.projectId?Number(route.query.projectId):null}),dates=ref([route.query.dateFrom||today(),route.query.dateTo||today()]),data=reactive({summary:{},results:[],facts:[],companies:[],projects:[],categories:[]}),personnel=reactive({rows:[],personnelCost:0,readyCount:0,issueCount:0,overAllocatedCount:0}),issuesOnly=ref(false),saving=ref(false)
const factDialog=ref(false),factReadOnly=ref(false),factForm=reactive({}),recalcDialog=ref(false),recalcForm=reactive({}),resultDrawer=ref(false),resultDetail=ref(null)
const summary=computed(()=>data.summary||{}),filteredProjects=computed(()=>query.companyDeptId?data.projects.filter(p=>Number(p.companyDeptId)===Number(query.companyDeptId)):data.projects)
const isBoss=computed(()=>userStore.roles.includes('admin')||userStore.permissions.includes('*:*:*')||userStore.permissions.includes('business:boss:view'))
const selectedCategory=computed(()=>data.categories.find(c=>Number(c.categoryId)===Number(factForm.categoryId)))
const categoryGroups=computed(()=>['REVENUE','COST','ADJUSTMENT','VALUE'].map(kind=>({kind,label:{REVENUE:'收入',COST:'成本费用',ADJUSTMENT:'核算调整',VALUE:'非金额成果'}[kind],items:data.categories.filter(c=>c.factKind===kind)})).filter(g=>g.items.length))
const statusLabel={DRAFT:'待确认',RETURNED:'已退回',CONFIRMED:'已确认',REVERSED:'已冲销',VOIDED:'已作废'},statusTone={DRAFT:'warning',RETURNED:'danger',CONFIRMED:'success',REVERSED:'warning',VOIDED:'info'}
const costStatusLabel={READY:'核算就绪',LEAVE:'今日请假',MISSING_REGION:'未设置国家',MISSING_COST:'未设置成本',LEGACY_COST:'需更新成本',MISSING_ALLOCATION:'未设置投入',OVER_ALLOCATED:'投入超100%'}
const costStatusTone={READY:'success',LEAVE:'info',MISSING_REGION:'danger',MISSING_COST:'danger',LEGACY_COST:'warning',MISSING_ALLOCATION:'warning',OVER_ALLOCATED:'danger'}
const inputSourceLabel={PLAN:'计划投入',ACTUAL:'确认实际',LEAVE:'今日请假'}
const visiblePersonnelRows=computed(()=>issuesOnly.value?(personnel.rows||[]).filter(row=>!['READY','LEAVE'].includes(row.costStatus)):(personnel.rows||[]))
const money=v=>Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:4}),signed=v=>`${Number(v||0)>0?'+':''}${money(v)}`
const regionLabel=value=>value==='VN'?'越南':value==='CN'?'中国':value||'—'
async function load(){const params={...query,dateFrom:dates.value?.[0],dateTo:dates.value?.[1]},[dashboardRes,personnelRes]=await Promise.all([getBusinessAccountingDashboard(params),getBusinessPersonnelCostOverview({...query,bizDate:dates.value?.[1]||today()})]);Object.assign(data,dashboardRes.data||{});Object.assign(personnel,personnelRes.data||{})}
function reset(){Object.assign(query,{companyDeptId:null,projectId:null});dates.value=[today(),today()];load()}
function openFact(row={},readOnly=false){factReadOnly.value=readOnly;Object.keys(factForm).forEach(k=>delete factForm[k]);Object.assign(factForm,{factId:null,projectId:null,bizDate:today(),categoryId:null,amount:null,quantity:null,currency:'CNY',unit:'',description:'',counterparty:'',attachmentUrls:'',remark:'',version:null,...row});factDialog.value=true}
function projectChanged(id){const p=data.projects.find(x=>Number(x.projectId)===Number(id));if(p)factForm.currency=p.currency||'CNY'}
async function saveFact(){if(factReadOnly.value)return;if(!factForm.projectId||!factForm.categoryId||!factForm.bizDate)return ElMessage.warning('请完整选择项目、日期和类别');if(!factForm.description?.trim())return ElMessage.warning('请填写收支说明');const wasReturned=factForm.status==='RETURNED';saving.value=true;try{await saveBusinessOperatingFact(factForm);factDialog.value=false;await load();ElMessage.success(wasReturned?'已修改并重新提交，等待老板确认':'收支草稿已保存')}finally{saving.value=false}}
async function confirmFact(row){await ElMessageBox.confirm('确认后将计入正式日报，不能直接修改，确定吗？','确认入账',{type:'warning'});await confirmBusinessOperatingFact(row.factId);await load();ElMessage.success('已确认入账并生成日结果')}
async function returnFact(row){const {value}=await ElMessageBox.prompt('请说明收支数据或凭证需要修改的内容','退回收支修改',{inputValidator:v=>!!v?.trim()||'必须填写退回原因',inputAttributes:{maxlength:500},type:'warning'});await returnBusinessOperatingFact(row.factId,{reason:value.trim()});await load();ElMessage.success('已退回提交人修改')}
async function reverseFact(row){const {value}=await ElMessageBox.prompt('请填写冲销原因','冲销已确认流水',{inputValidator:v=>!!v?.trim()||'必须填写冲销原因',type:'warning'});await reverseBusinessOperatingFact(row.factId,{reason:value});await load();ElMessage.success('已冲销并重新生成日结果')}
function openRecalculate(){Object.assign(recalcForm,{projectId:query.projectId||null,bizDate:dates.value?.[1]||today()});recalcDialog.value=true}
async function saveRecalculate(){if(!recalcForm.projectId||!recalcForm.bizDate)return ElMessage.warning('请选择项目和日期');saving.value=true;try{await recalculateBusinessProjectDay(recalcForm);recalcDialog.value=false;await load();ElMessage.success('项目日结果已生成新版本')}finally{saving.value=false}}
async function openResult(row){resultDetail.value=(await getBusinessDailyResult(row.resultId)).data;resultDrawer.value=true}
function openStaffCost(row){router.push({path:'/business/staff',query:{userId:row.userId,action:'cost'}})}
function openStaffProfile(row){router.push({path:'/business/staff',query:{userId:row.userId,action:'edit'}})}
function openAllocation(row){router.push({path:'/business/projects',query:{id:row.projectId,tab:'operating'}})}
load()
</script>

